DECLARE @start_date DATE = DATEADD(year, -1, DATEADD(month, DATEDIFF(month, 0, GETDATE()), 0));
DECLARE @end_date DATE = DATEADD(day, -1, DATEADD(month, 1, @start_date));

SELECT *
FROM prescriptions
WHERE prescriptions.subject_id = 10040025
AND prescriptions.starttime >= @start_date
AND prescriptions.starttime <= @end_date;
